let area1, area2;
let inTransition = false;
let timeTrigger, easingFunc, easingFuncs;
const timing = [1, 2]; // in seconds [transition, still]
const numOfSlpits = 100;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	describe('transition between two states of shapes');
	frameRate(60);

	easingFuncs = [easeInOutBack, easeInOutElastic,easeOutBounce];
	easingFunc = random(easingFuncs);

	area1 = initArea(numOfSlpits);
	area2 = initArea(numOfSlpits);

	setNextTrigger();
}

