function setNextTrigger() {
	timeTrigger = millis() + timing[inTransition ? 0 : 1] * 1000;
}

function draw() {
	// trigger reached?
	if (millis() > timeTrigger) {
		// console.log("" + (millis() > timeTrigger) + ", " + inTransition);
		setNextTrigger();
		if (inTransition) {
			area1 = area2;
			area2 = initArea(numOfSlpits);
			easingFunc = random(easingFuncs);
		}
		inTransition = !inTransition;
	}

	if (inTransition) {
		const t = easingFunc(1 - (timeTrigger - millis()) / (timing[1] * 1000));
		let bg = lerpColor(color(area1.bg), color(area2.bg), t);
		bg.setAlpha(48);
		background(bg);
		area1.show(area2, t);
		// area1.show();

	} else {
		var bg = color(area1.bg);
		bg.setAlpha(48);
		background(bg);
		// just show area1
		area1.show();

	}
}

// https://easings.net/
function easeInOutElastic(x) {
	const c5 = (2 * Math.PI) / 4.5;
	return x === 0
		? 0
		: x === 1
		? 1
		: x < 0.5
		? -(Math.pow(2, 20 * x - 10) * Math.sin((20 * x - 11.125) * c5)) / 2
		: (Math.pow(2, -20 * x + 10) * Math.sin((20 * x - 11.125) * c5)) / 2 + 1;
}
function easeOutBounce(x) {
	const n1 = 7.5625;
	const d1 = 2.75;

	if (x < 1 / d1) {
			return n1 * x * x;
	} else if (x < 2 / d1) {
			return n1 * (x -= 1.5 / d1) * x + 0.75;
	} else if (x < 2.5 / d1) {
			return n1 * (x -= 2.25 / d1) * x + 0.9375;
	} else {
			return n1 * (x -= 2.625 / d1) * x + 0.984375;
	}
}
function easeInOutBack(x){
	const c1 = 1.70158;
	const c2 = c1 * 1.525;

	return x < 0.5
		? (Math.pow(2 * x, 2) * ((c2 + 1) * 2 * x - c2)) / 2
		: (Math.pow(2 * x - 2, 2) * ((c2 + 1) * (x * 2 - 2) + c2) + 2) / 2;
}

