function mRand(v1, v2) {
	const vd = (v2 - v1);
	return floor(v1 + random(vd * 0.3, vd * 0.7))
}
function mFract(v1, v2, f) {
	var vd = (v2 - v1);
	return floor(v1 + vd * f);
}

class Area {
	constructor(pal) {
		this.pal = pal;
		this.objs = [];
		this.bg = random(this.pal);
		const p1 = createVector(0, 0);
		const p2 = createVector(width, 0);
		const p3 = createVector(width, height);
		const p4 = createVector(0, height);
		const clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});

		// probability to make hotizontal split
		this.prob = height/(width+height)
	}

	split(num = 1) {
		for (let i = 0; i < num; i++) {
			if ((i + frameCount) % 2 === 1) {
				this.divide();
			} else {
				this.divide_chaos();
			}
		}
	}

	divide() {
		const last = random(this.objs); // this.objs[this.objs.length-1]
		var p1 = last.p1.copy();
		var p2 = last.p2.copy();
		var p3 = last.p3.copy();
		var p4 = last.p4.copy();

		const f1 = random(0.3, 0.7);
		const f2 = random(0.3, 0.7);

		if (random() < this.prob) {
			// horizontal split

			p1.y = mFract(p1.y, p4.y, f1);
			last.p4.y = p1.y
			p1.x = mFract(p1.x, p4.x, f1);
			last.p4.x = p1.x

			p2.y = mFract(p2.y, p3.y, f2);
			last.p3.y = p2.y
			p2.x = mFract(p2.x, p3.x, f2);
			last.p3.x = p2.x

		} else {
			// vertical
			p1.x = mFract(p1.x, p2.x, f1);
			last.p2.x = p1.x
			p1.y = mFract(p1.y, p2.y, f1);
			last.p2.y = p1.y

			p4.x = mFract(p3.x, p4.x, f2);
			last.p3.x = p4.x
			p4.y = mFract(p3.y, p4.y, f2);
			last.p3.y = p4.y
		}

		var clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}	

	divide_chaos() {
		var last = random(this.objs); // this.objs[this.objs.length-1]
		var p1 = last.p1.copy();
		var p2 = last.p2.copy();
		var p3 = last.p3.copy();
		var p4 = last.p4.copy();

		if (random() < this.prob) {
			// horizontal split
			p1.y = mRand(p1.y, p4.y);
			p2.y = mRand(p2.y, p3.y);
			last.p4.y = p1.y
			last.p3.y = p2.y
		} else {
			// vertical
			p1.x = mRand(p1.x, p2.x);
			p4.x = mRand(p3.x, p4.x);
			last.p2.x = p1.x
			last.p3.x = p4.x
		}

		var clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}	

	divide_straight_lines() {
		var last = random(this.objs); // this.objs[this.objs.length-1]
		var p1 = last.p1.copy();
		var p2 = last.p2.copy();
		var p3 = last.p3.copy();
		var p4 = last.p4.copy();

		if (random() < this.prob) {
			// horizontal split
			p1.y = mRand(p1.y, p4.y);
			p2.y = p1.y
			last.p4.y = p1.y
			last.p3.y = p1.y
		} else {
			// vertical
			p1.x = mRand(p1.x, p2.x);
			p4.x = p1.x
			last.p2.x = p1.x
			last.p3.x = p1.x
		}

		var clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}

	show(other, t) {
		// console.log("" + inTransition + " " + t);
		if (other && this.objs.length !== other.objs.length) {
			console.log("areas have different obj.length: " + this.objs.length + ", " + other.objs.length);
		}

		push();
		// blendMode(DIFFERENCE)
		noStroke();
		// for (let o of this.objs) {
		for (let i = 0; i < this.objs.length; i++) {
			let o = this.objs[i];
			var clr = color(o.clr);
			var p1 = o.p1.copy();
			var p2 = o.p2.copy();
			var p3 = o.p3.copy();
			var p4 = o.p4.copy();

			// if transition
			if (other && i < other.objs.length) {
				p1 = p5.Vector.lerp(p1, other.objs[i].p1, t);
				p2 = p5.Vector.lerp(p2, other.objs[i].p2, t);
				p3 = p5.Vector.lerp(p3, other.objs[i].p3, t);
				p4 = p5.Vector.lerp(p4, other.objs[i].p4, t);
				clr = lerpColor(clr, color(other.objs[i].clr), t);
			}

			clr.setAlpha(128)
			fill(clr);

			quad(p1.x, p1.y, 
					 p2.x, p2.y,
					 p3.x, p3.y, 
					 p4.x, p4.y)
		}

		fill(255, 128)
		rect(0, 0, (1 - this.objs.length/100) * width, 20)

		pop();
	}
}
